/**
 * @param {number} m
 * @param {number} n
 * @return {string[]}
 */
var createGrid = function(m, n) {
    return Array.from({ length: m }, (_, i) => (i === 0 ? '.' : '#').repeat(n - 1) + '.');
};

/**
 * @param {number} m
 * @param {number} n
 * @return {string[]}
 */
var createGrid = function(m, n) {
    const first = '.'.repeat(n);
    const others = '#'.repeat(n - 1) + '.';

    return [first].concat(Array.from({ length: m - 1 }, () => others));
};

/**
 * @param {number} m
 * @param {number} n
 * @return {string[]}
 */
var createGrid = function(m, n) {
    const first = '.'.repeat(n);
    const others = '#'.repeat(n - 1) + '.';

    const res = Array(m);
    res[0] = first;

    for (let i = 1; i < m; i++) {
        res[i] = others;
    }

    return res;
};
